// Bad: new function each render
<Row onClick={() => save()} />

// Good: same function every render
const save = useCallback(() => doSave(), []);
<Row onClick={save} />

// Bad: new object each render
<Row style={{ color: "red" }} />

// Good: same object every render
const RED = { color: "red" };
<Row style={RED} />

// Bad: new array each render
<Row items={["a", "b"]} />

// Good: same array every render
const ITEMS = ["a", "b"];
<Row items={ITEMS} />

